import React from 'react';
import DatasetCard from './DatasetCard';

export default function DatasetTable({ datasets }) {
  return (
    <div className="bg-card-light dark:bg-card-dark border rounded shadow-sm">
      <div className="p-4 border-b font-semibold text-textPrimary-light dark:text-textPrimary-dark">Name</div>
      {datasets.map((_, index) => (
        <DatasetCard key={index} index={index} />
      ))}
    </div>
  );
}
